  twoAirports: /Arthur.?s Town Airport/i.test(pageText.island) && /New Bight Airport/i.test(pageText.island),
  mountHeight: /206\s*(feet|ft)|63\s*m/i.test(pageText.mount + ' ' + pageText.hermitage),
  hermitageHistory: /1939/i.test(pageText.mount + ' ' + pageText.hermitage) && /stone staircase|rocky incline/i.test(pageText.hermitage),
  nasaRights: /NASA/i.test(pageText.nasa) && /public domain/i.test(pageText.nasa),
